namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ── CalculateTotal: DataRow-driven happy-path tests ──────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0,  10.00,  DisplayName = "Single item, no tax")]
    [DataRow(10.00, 2, 0.0,  20.00,  DisplayName = "Two items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00,  DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62,  DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00,  5, 0.10,  0.00,  DisplayName = "Zero price yields zero total")]
    [DataRow(10.00, 0, 0.10,  0.00,  DisplayName = "Zero quantity yields zero total")]
    [DataRow(99.99, 1, 1.0, 199.98,  DisplayName = "100% tax doubles the price")]
    public void CalculateTotal_ValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expectedTotal)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expectedTotal, result);
    }

    // ── CalculateTotal: invalid-input tests via DataRow ──────────────────

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, "unitPrice",  DisplayName = "Negative price throws")]
    [DataRow(10.00, -1, 0.10, "quantity",   DisplayName = "Negative quantity throws")]
    [DataRow(10.00, 1, -0.01, "taxRate",    DisplayName = "Negative tax rate throws")]
    [DataRow(10.00, 1, 1.01,  "taxRate",    DisplayName = "Tax rate > 1 throws")]
    public void CalculateTotal_InvalidInputs_ThrowsArgumentOutOfRangeException(
        double unitPrice, int quantity, double taxRate, string expectedParamName)
    {
        var ex = Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParamName, ex.ParamName);
    }

    // ── ApplyDiscount: DynamicData from a method ─────────────────────────

    [TestMethod]
    [DynamicData(nameof(ApplyDiscountTestData), DynamicDataSourceType.Method)]
    public void ApplyDiscount_ValidInputs_ReturnsExpectedPrice(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<object[]> ApplyDiscountTestData()
    {
        yield return [100m,   0m, 100m];    // No discount
        yield return [100m,  10m,  90m];    // 10% off
        yield return [200m,  25m, 150m];    // 25% off
        yield return [100m, 100m,   0m];    // 100% off (free)
        yield return [59.99m, 15m, 50.9915m]; // Fractional price & discount
    }

    // ── ApplyDiscount: DynamicData from a property ───────────────────────

    [TestMethod]
    [DynamicData(nameof(ApplyDiscountInvalidData), DynamicDataSourceType.Property)]
    public void ApplyDiscount_InvalidDiscount_ThrowsArgumentOutOfRangeException(
        decimal price, decimal discountPercent)
    {
        var ex = Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));

        Assert.AreEqual("discountPercent", ex.ParamName);
    }

    public static IEnumerable<object[]> ApplyDiscountInvalidData =>
    [
        [100m, -1m],     // Negative discount
        [100m, 101m],    // Discount exceeds 100%
        [50m,  -0.01m],  // Barely negative
        [50m,  100.01m], // Just over the cap
    ];

    // ── FormatPrice: quick DataRow coverage ──────────────────────────────

    [TestMethod]
    [DataRow(19.99, "$", "$19.99",  DisplayName = "Default dollar symbol")]
    [DataRow(19.99, "€", "€19.99",  DisplayName = "Euro symbol")]
    [DataRow(5.5,   "$", "$5.50",   DisplayName = "Pads to two decimals")]
    [DataRow(0.0,   "£", "£0.00",   DisplayName = "Zero price formatted")]
    public void FormatPrice_ReturnsCorrectlyFormattedString(
        double price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }
